JQRichTextModel.EVENT_CURSOR_FORMAT_CHANGED = "cursor-format-changed"

function JQRichTextModel:ctor(data)
    if not data or not data.inServer then
        cc.load("event").new():bind(self)
    end
    self:initData(data)
end

function JQRichTextModel:initData(data)
    data = data or {}
    self.isFixedGroupAlign = false
    self.defaultFormat = data.defaultFormat or JQRichTextFormatModel.new()
    self.dataNotification = ternary(data.dataNotification == false, false, true)
    self.formats = {}
    self.cursors = {}
    self.backupFormats = {}
    self.backupCursors = {}
    self:setText(data.text)
end

function JQRichTextModel:dispatchEvent(...)
    -- The server model has no cocos event bus; richtext_manager emits protocol responses.
end

--- 设置默认样式，如果使用，请一定要在setText之前调用
function JQRichTextModel:setDefaultFormat(defaultFormat)
    self.defaultFormat = defaultFormat
end

function JQRichTextModel:mergeDefaultFormat(defaultFormat)
   self.defaultFormat:merge(defaultFormat)
end

function JQRichTextModel:setFixedGroupAlign(isFixed)
    self.isFixedGroupAlign = isFixed
end

function JQRichTextModel:setText(text, needResetCursor, isFromReplay)
    text = (text or "") == "" and JQRichTextConstants.DEFAULT_TEXT or text
    self.formats = JQRichTextHtmlParser.new(self.defaultFormat):parse(text)
    self:resetGroupIndexSeed()
    self:mergeFormat(self.formats, false)
    self:adjustFormatGroupIndex()
    if needResetCursor ~= false then
        self:resetAllCursorIndices()
    end
    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent()
    end
end

function JQRichTextModel:getFormats()
    return clone(self.formats)
end

function JQRichTextModel:setDataNotification(dataNotification)
    self.dataNotification = dataNotification
end

function JQRichTextModel:serialize()
    return JQRichTextSerialization.new():serialize(clone(self.formats), self.defaultFormat)
end

function JQRichTextModel:resetGroupIndexSeed()
    local groupIndexSeed = 0
    table.foreach(self.formats, function(_, format)
        groupIndexSeed = math.max(groupIndexSeed, format.groupIndex)
    end)
    groupIndexSeed = groupIndexSeed + 1
    JQRichTextUtils:updateGroupIndexSeed(groupIndexSeed)
end

function JQRichTextModel:deleteAheadChar(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    if cursor:isSelected() then
        self:deleteCharsAtRange(uid, isFromReplay)
    else
        self:deleteAheadCharSingle(uid, isFromReplay)
    end
    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent()
    end
end

function JQRichTextModel:deleteAheadCharSingle(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local index, formatIndex, charIndex, inFront
    index, inFront = cursor:getEndedIndex()
    formatIndex, charIndex, inFront = self:getFormatIndicesByIndex(index, inFront)

    local format = self.formats[formatIndex]
    local deletingCharIndex = inFront and charIndex - 1 or charIndex
    local newIndex, newFormatIndex, newCharIndex, newInFront = index, formatIndex, charIndex, inFront
    if deletingCharIndex > 0 then
        newFormatIndex, newCharIndex, newInFront = self:deleteAheadCharInNode(formatIndex, deletingCharIndex, inFront)
    elseif formatIndex > 1 then
        newFormatIndex, newCharIndex, newInFront = self:deleteAheadCharAstrideNode(formatIndex, deletingCharIndex, inFront)
    elseif format.groupAlign ~= JQRichTextConstants.ALIGNMENT_LEFT then
        if not self.isFixedGroupAlign then
            self:setGroupFromIndex(formatIndex, JQRichTextUtils:newGroupIndex(), JQRichTextConstants.ALIGNMENT_LEFT)
        end
    end

    if newFormatIndex == 1 and newCharIndex < 1 then
        newFormatIndex, newInFront = 1, true
    end
    newIndex, newInFront = self:getIndexByFormatIndices(newFormatIndex, newCharIndex, newInFront)
    cursor:setIndices(newIndex, newInFront)
    self:updateCursorGroupByFormatIndex(uid, isFromReplay)
    self:mergeFormat(self.formats, false)
    self:updateOtherCursorIndicesByDeleteAhead(uid, index, inFront)
end

function JQRichTextModel:deleteAheadCharInNode(formatIndex, charIndex, inFront)
    local format = self.formats[formatIndex]
    if charIndex > format:getLength() then
        format:deleteLastChar()
    else
        format:deleteChar(charIndex, 1)
    end
    if format:getOriginalLength() == 0 and self:getFormatCountOfGroupIndex(format.groupIndex) == 1 then
        format:setNullString(true)
    end
    charIndex = charIndex - 1
    if charIndex == 0 then
        if format:getLength() > 0 then
            charIndex, inFront = 1, true
        else
            charIndex, inFront = 1, true
        end
    else
        inFront = false
    end
    return formatIndex, charIndex, inFront
end

function JQRichTextModel:deleteAheadCharAstrideNode(formatIndex, charIndex, inFront)
    local format = self.formats[formatIndex]
    local nextFormatIndex = formatIndex - 1
    local nextFormat = self.formats[nextFormatIndex]
    if format.groupAlign == JQRichTextConstants.ALIGNMENT_LEFT or self.isFixedGroupAlign then
        if format.groupAlign == nextFormat.groupAlign then
            if format.groupIndex == nextFormat.groupIndex then
                if format:getLength() == 0 then
                    table.remove(self.formats, formatIndex)
                else
                    nextFormat:deleteLastChar()
                end
                formatIndex, charIndex, inFront = nextFormatIndex, nextFormat:getLength(), false
            else
                self:setGroupFromIndex(formatIndex, nextFormat.groupIndex, nextFormat.groupAlign)
                if format:getOriginalLength() == 1 and (format.tailWithLF or format.nullString) then
                    table.remove(self.formats, formatIndex)
                end
                if nextFormat.tailWithLF then
                    nextFormat:deleteLastChar()
                end
                formatIndex, charIndex, inFront = nextFormatIndex, nextFormat:getLength(), false
            end
        else
            self:setGroupFromIndex(formatIndex, nextFormat.groupIndex, nextFormat.groupAlign)
            if format:getLength() == 0 then
                format:deleteLastChar()
            elseif nextFormat.tailWithLF then
                nextFormat:deleteLastChar()
            end
            if format:getOriginalLength() == 0 then
                table.remove(self.formats, formatIndex)
            end
            formatIndex, charIndex, inFront = nextFormatIndex, nextFormat:getLength(), false
        end
    else
        self:setGroupFromIndex(formatIndex, JQRichTextUtils:newGroupIndex(), JQRichTextConstants.ALIGNMENT_LEFT)
        charIndex, inFront = 1, true
    end
    return formatIndex, charIndex, inFront
end

function JQRichTextModel:deleteBehindChar(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    if cursor:isSelected() then
        self:deleteCharsAtRange(uid, isFromReplay)
    else
        self:deleteBehindCharSingle(uid, isFromReplay)
    end
    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent()
    end
end

function JQRichTextModel:deleteBehindCharSingle(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local index, formatIndex, charIndex, inFront
    index, inFront = cursor:getEndedIndex()
    formatIndex, charIndex, inFront = self:getFormatIndicesByIndex(index, inFront)

    local format = self.formats[formatIndex]
    local deletingCharIndex = inFront and charIndex or charIndex + 1
    local newIndex, newFormatIndex, newCharIndex, newInFront = index, formatIndex, charIndex, inFront

    local deleted = false
    if deletingCharIndex <= format:getLength() then
        deleted = true
        newFormatIndex, newCharIndex, newInFront = self:deleteBehindCharInNode(formatIndex, deletingCharIndex, inFront)
    elseif formatIndex < #self.formats then
        deleted = true
        newFormatIndex, newCharIndex, newInFront = self:deleteBehindCharAstrideNode(formatIndex)
    end

    newIndex, newInFront = self:getIndexByFormatIndices(newFormatIndex, newCharIndex, newInFront)
    cursor:setIndices(newIndex, newInFront)
    self:updateCursorGroupByFormatIndex(uid, isFromReplay)
    self:mergeFormat(self.formats, false)
    if deleted then
        self:updateOtherCursorIndicesByDeleteBehind(uid, index, inFront)
    end
end

function JQRichTextModel:deleteBehindCharInNode(formatIndex, charIndex, inFront)
    local format = self.formats[formatIndex]
    if charIndex <= format:getLength() then
        format:deleteChar(charIndex, 1)
    else
        format:deleteLastChar()
    end
    local length = format:getLength()
    if charIndex == length then
        inFront = true
    elseif charIndex > length then
        charIndex, inFront = charIndex - 1, false
    end
    if charIndex <= 0 then
        charIndex, inFront = 1, true
    end
    return formatIndex, charIndex, inFront
end

function JQRichTextModel:deleteBehindCharAstrideNode(formatIndex)
    local format = self.formats[formatIndex]
    local nextFormatIndex = formatIndex + 1
    local nextFormat = self.formats[nextFormatIndex]
    if format.groupIndex ~= nextFormat.groupIndex then
        if format.tailWithLF then
            format:deleteLastChar()
        end
        self:setGroupFromIndex(nextFormatIndex, format.groupIndex, format.groupAlign)
    else
        if format.tailWithLF then
            format:deleteLastChar()
        else
            nextFormat:deleteChar(1, 1)
        end
    end
    return nextFormatIndex, 1, true
end

function JQRichTextModel:deleteCharsAtRange(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local beganIndex, beganInFront, endedIndex, endedInFront = cursor:getIndices()
    if beganIndex > endedIndex or (beganIndex == endedIndex and not beganInFront) then
        beganIndex, endedIndex = endedIndex, beganIndex
        beganInFront, endedInFront = endedInFront, beganInFront
    end

    local beganFormatIndex, beganCharIndex, endedFormatIndex, endedCharIndex
    beganFormatIndex, beganCharIndex, beganInFront = self:getFormatIndicesByIndex(beganIndex, beganInFront)
    endedFormatIndex, endedCharIndex, endedInFront = self:getFormatIndicesByIndex(endedIndex, endedInFront)

    if beganFormatIndex ~= endedFormatIndex then
        self:deleteCharsToHead(endedFormatIndex, endedCharIndex, endedInFront)
        self:deleteCharsToTail(beganFormatIndex, beganCharIndex, beganInFront)
        for i = endedFormatIndex - 1, beganFormatIndex + 1, -1 do
            table.remove(self.formats, i)
            endedFormatIndex = endedFormatIndex - 1
        end
        local beganFormat = self.formats[beganFormatIndex]
        self:setGroupFromIndex(endedFormatIndex, beganFormat.groupIndex, beganFormat.groupAlign)
    else
        self:deleteCharsInNode(beganFormatIndex, beganCharIndex, beganInFront, endedCharIndex, endedInFront)
    end

    cursor:setIndices(beganIndex, beganInFront)
    self:updateCursorGroupByFormatIndex(uid, isFromReplay)
    self:mergeFormat(self.formats, false)
    self:updateOtherCursorIndicesByDeleteRange(uid, beganIndex, beganInFront, endedIndex, endedInFront)
end

function JQRichTextModel:deleteCharsToTail(formatIndex, index, inFront)
    local format = self.formats[formatIndex]
    local length = format:getLength()
    local fromIndex = index + (inFront and 0 or 1)
    local deletedLen = length - fromIndex + 1
    if deletedLen > 0 then
        format:deleteChar(fromIndex, deletedLen)
    end
    format:setTailWithLF(false)
    format:setNullString(false)
end

function JQRichTextModel:deleteCharsToHead(formatIndex, index, inFront)
    local format = self.formats[formatIndex]
    local length = format:getLength()
    local toIndex = index + (inFront and -1 or 0)
    local deletedLen = toIndex
    if deletedLen > 0 then
        format:deleteChar(1, deletedLen)
    end
    if toIndex > length then
        format:setTailWithLF(false)
        format:setNullString(false)
    end
end

function JQRichTextModel:deleteCharsInNode(formatIndex, beganIndex, beganInFront, endedIndex, endedInFront)
    local format = self.formats[formatIndex]
    local length = format:getLength()
    local fromIndex = beganIndex + (beganInFront and 0 or 1)
    local toIndex = endedIndex + (endedInFront and -1 or 0)
    if fromIndex <= toIndex then
        format:deleteChar(fromIndex, toIndex - fromIndex + 1)
    end
    if toIndex > length then
        format:setTailWithLF(false)
        format:setNullString(false)
    end
end

function JQRichTextModel:insertChar(uid, char, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local index, formatIndex, charIndex, inFront
    index, inFront = cursor:getEndedIndex()
    formatIndex, charIndex, inFront = self:getFormatIndicesByIndex(index, inFront)

    local format = self.formats[formatIndex]
    local insertingCharIndex = inFront and charIndex or charIndex + 1
    local newIndex, newInFront = index, inFront

    if char ~= "\n" and JQRichTextUtils:isTextSimilar(format, cursor.format) then
        if charIndex == format:getOriginalLength() and format.tailWithLF and not inFront then
            local newFormat = format:clone()
            newFormat:setText(char)
            newFormat:setTailWithLF(false)
            table.insert(self.formats, formatIndex + 1, newFormat)
        else
            format:insertChar(insertingCharIndex, char)
        end
    else
        local sections = format:split(insertingCharIndex, char, cursor.format)
        self:switchLF(sections)
        self:mergeFormat(sections, true)
        table.remove(self.formats, formatIndex)
        table.foreach(sections, function(i, section)
            table.insert(self.formats, formatIndex + i - 1, section)
        end)
    end

    newIndex, newInFront = index + (inFront and 0 or string.utf8len(char)), false
    cursor:setIndices(newIndex, newInFront)

    self:mergeFormat(self.formats, false)
    self:adjustFormatGroupIndex()
    self:updateCursorGroupByFormatIndex(uid, isFromReplay)
    self:updateOtherCursorIndicesByInsert(uid, index, inFront, char)

    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent()
    end
end

function JQRichTextModel:switchLF(formats)
    local index = 1
    while (index <= #formats) do
        if formats[index].text == "\n" then
            formats[index]:setText("")
            if formats[index].tailWithLF then
                table.insert(formats, index + 1, formats[index]:clone())
            else
                formats[index]:setTailWithLF(true)
            end
        end
        index = index + 1
    end
end

function JQRichTextModel:mergeFormat(formats, onlyCheckText)
    local index = 2
    while (index <= #formats) do
        local this = formats[index - 1]
        local other = formats[index]
        local isSimilar = onlyCheckText and JQRichTextUtils:isTextSimilar(this, other) or JQRichTextUtils:isFormatSimilar(this, other)
        if other:getOriginalLength() == 0 then
            table.remove(formats, index)
        elseif JQRichTextUtils:isAlignEqual(this, other) then
            if other:getOriginalLength() == 1 and other.tailWithLF and not this.tailWithLF then
                this:setTailWithLF(true)
                table.remove(formats, index)
            elseif not this.tailWithLF and isSimilar then
                JQRichTextUtils:mergeFormat(this, other)
                table.remove(formats, index)
            else
                index = index + 1
            end
        else
            index = index + 1
        end
    end
end

function JQRichTextModel:adjustFormatGroupIndex()
    local lastGroupIndex = -1
    local newGroupIndex = 0
    table.foreach(self.formats, function(_, format)
        if format.groupIndex ~= lastGroupIndex then
            lastGroupIndex = format.groupIndex
            newGroupIndex = newGroupIndex + 1
        end
        format:setGroupIndex(newGroupIndex)
    end)
end

function JQRichTextModel:getFormatCountOfGroupIndex(groupIndex)
    local formatCount = 0
    table.foreach(self.formats, function(_, format)
        if format.groupIndex == groupIndex then
            formatCount = formatCount + 1
        end
    end)
    return formatCount
end

function JQRichTextModel:getFormatIndicesByIndex(charIndex, inFront)
    for formatIndex, format in ipairs(self.formats) do
        local length = format:getOriginalLength()
        if length > charIndex then
            return formatIndex, charIndex, inFront
        elseif length == charIndex then
            if not format.tailWithLF or (format.tailWithLF and inFront) then
                return formatIndex, charIndex, inFront
            end
        end
        charIndex = charIndex - length
    end
    charIndex, inFront = self.formats[#self.formats]:getOriginalLength(), false
    return #self.formats, charIndex, inFront
end

function JQRichTextModel:getIndexByFormatIndices(formatIndex, charIndex, inFront)
    local index = 0
    for i = 1, formatIndex - 1 do
        index = index + self.formats[i]:getOriginalLength()
    end
    local originalLength = self.formats[formatIndex]:getOriginalLength()
    if charIndex <= 0 then
        charIndex, inFront = 1, true
    end
    if charIndex > originalLength then
        charIndex, inFront = originalLength, false
    end
    index = index + charIndex
    return index, inFront
end

function JQRichTextModel:getTotalLength()
    local length = 0
    table.foreach(self.formats, function(_, format)
        length = length + format:getOriginalLength()
    end)
    return length
end

function JQRichTextModel:getRealLength()
    local length = 0
    table.foreach(self.formats, function(_, format)
        length = length + format:getRealLength()
    end)
    return length
end

function JQRichTextModel:setGroupFromIndex(index, groupIndex, groupAlign)
    local oldGroupIndex = self.formats[index].groupIndex
    while (index <= #self.formats) do
        local format = self.formats[index]
        if format.groupIndex ~= oldGroupIndex then break end
        format:setGroup(groupIndex, groupAlign)
        if format.tailWithLF or format.nullString then break end
        index = index + 1
    end
end

function JQRichTextModel:updateDefaultFormatByName(uid, formatName, formatValue, isFromReplay)
    local format = {}
    formatValue = self:convertToColor(formatName, formatValue, format)
    format[formatName] = formatValue

    self:updateDefaultFormatInFormats(formatName, formatValue)

    self.defaultFormat:merge(format)

    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent(uid)
    end
end

function JQRichTextModel:updateDefaultFormatInFormats(formatName, formatValue)
    table.walk(self.formats, function(format)
        self:updateFormatDefaultProperties(format, formatName, formatValue)
    end)

    table.walk(self.cursors, function(cursor)
        self:updateFormatDefaultProperties(cursor.format, formatName, formatValue)
    end)
end

function JQRichTextModel:updateFormatDefaultProperties(format, formatName, formatValue)
    if formatName == JQRichTextConstants.HTML.FORMAT_COLOR then
        if JQRichTextUtils:isColorEqual(format[formatName], self.defaultFormat.color) then
            format:setColor(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_FONT_NAME then
        if format[formatName] == self.defaultFormat.fontName then
            format:setFontName(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_FONT_SIZE then
        if format[formatName] == self.defaultFormat.fontSize then
            format:setFontSize(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_UNDERLINE then
        if format[formatName] == self.defaultFormat.underlineWidth then
            format:setUnderlineWidth(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_BOLD then
        if format[formatName] == self.defaultFormat.bold then
            format:setBold(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
        if not format.hasBgColor or JQRichTextUtils:isColorEqual(format.bgColor, self.defaultFormat.bgColor) then
            format:setBgColor(formatValue)
        end
    elseif formatName == JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN then
        if format[formatName] == self.defaultFormat.groupAlign then
            format:setGroupAlign(formatValue)
        end
    end
end

function JQRichTextModel:updateFullFormatsByName(uid, formatName, formatValue, groupIndex, isFromReplay)
    local indices = {
        beganIndex = 1,
        beganInFront = true,
        endedIndex = self:getTotalLength(),
        endedInFront = false
    }
    self:updateFormatsAtRangeByName(uid, indices, formatName, formatValue, groupIndex, isFromReplay)
end

function JQRichTextModel:updateFormatsByName(uid, formatName, formatValue, groupIndex, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local beganIndex, beganInFront, endedIndex, endedInFront = cursor:getIndices()
    local indices = {
        beganIndex = beganIndex,
        beganInFront = beganInFront,
        endedIndex = endedIndex,
        endedInFront = endedInFront
    }
    self:updateFormatsAtRangeByName(uid, indices, formatName, formatValue, groupIndex, isFromReplay)
end

function JQRichTextModel:updateFormatsAtRangeByName(uid, indices, formatName, formatValue, groupIndex, isFromReplay)
    local format = {}
    formatValue = self:convertToColor(formatName, formatValue, format)
    format[formatName] = formatValue
    if formatName == JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN then
        format[JQRichTextConstants.HTML.FORMAT_GROUP_INDEX] = groupIndex
    end
    self:updateFormats(uid, indices, format, isFromReplay, formatName)

    if formatName == JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN then
        self:updateCursorGroupByFormatIndex(uid, isFromReplay)
    else
        self:updateCursorFormatByName(uid, formatName, formatValue, isFromReplay)
    end
end

function JQRichTextModel:updateFormats(uid, indices, format, isFromReplay, formatName)
    local beganIndex, beganInFront = indices.beganIndex, indices.beganInFront
    local endedIndex, endedInFront = indices.endedIndex, indices.endedInFront
    if beganIndex > endedIndex then
        beganIndex, endedIndex = endedIndex, beganIndex
        beganInFront, endedInFront = endedInFront, beganInFront
    end

    local totalLength = self:getTotalLength()
    if beganIndex > totalLength then
        local clonedFormat = self.formats[#self.formats]:clone()
        clonedFormat:setNullString(true)
        table.insert(self.formats, clonedFormat)
        beganIndex, endedIndex = totalLength + 1, totalLength + 1
    end

    local beganFormatIndex, beganCharIndex, endedFormatIndex, endedCharIndex
    beganFormatIndex, beganCharIndex, beganInFront = self:getFormatIndicesByIndex(beganIndex, beganInFront)
    endedFormatIndex, endedCharIndex, endedInFront = self:getFormatIndicesByIndex(endedIndex, endedInFront)

    for index = beganFormatIndex + 1, endedFormatIndex - 1 do
        self.formats[index]:merge(format)
    end

    if beganFormatIndex == endedFormatIndex then
        local sliceIndices = {
            beganIndex = beganCharIndex, beganInFront = beganInFront,
            endedIndex = endedCharIndex, endedInFront = endedInFront
        }
        self:sliceFormatAtRange(endedFormatIndex, sliceIndices, format)
    else
        local sliceIndices = {
            beganIndex = 1, beganInFront = true,
            endedIndex = endedCharIndex, endedInFront = endedInFront
        }
        self:sliceFormatAtRange(endedFormatIndex, sliceIndices, format)

        sliceIndices = {
            beganIndex = beganCharIndex, beganInFront = beganInFront,
            endedIndex = self.formats[beganFormatIndex]:getOriginalLength(), endedInFront = false
        }
        self:sliceFormatAtRange(beganFormatIndex, sliceIndices, format)
    end

    self:mergeFormat(self.formats, false)
    self:adjustFormatGroupIndex()

    if self.dataNotification and not isFromReplay then
        self:dispatchChangedEvent(uid,formatName)
    end
end

function JQRichTextModel:sliceFormatAtRange(formatIndex, indices, format)
    local beganIndex = indices.beganInFront and indices.beganIndex or indices.beganIndex + 1
    local endedIndex = indices.endedInFront and indices.endedIndex - 1 or indices.endedIndex

    if endedIndex < beganIndex then return end

    local sections = self.formats[formatIndex]:slice(beganIndex, endedIndex, format)
    table.remove(self.formats, formatIndex)
    table.foreach(sections, function(index, section)
        table.insert(self.formats, formatIndex + index - 1, section)
    end)
end

function JQRichTextModel:updateOtherCursorIndicesByInsert(uid, oldIndex, oldInFront, char)
    local charLength = string.utf8len(char)

    self:updateOtherCursorIndicesWithOffset(uid, oldIndex, oldInFront, charLength)
end

function JQRichTextModel:updateOtherCursorIndicesByDeleteRange(uid, beganIndex, beganInFront, endedIndex, endedInFront)
    if beganIndex > endedIndex or (beganIndex == endedIndex and not beganInFront) then
        beganIndex, endedIndex = endedIndex, beganIndex
        beganInFront, endedInFront = endedInFront, beganInFront
    end
    beganIndex = beganIndex + (beganInFront and 0 or 1)
    endedIndex = endedIndex + (endedInFront and -1 or 0)
    local deletedCnt = endedIndex - beganIndex + 1
    local totalLength = self:getTotalLength()

    local function getDeletedCursorIndices(index, inFront, isBegan)
        local otherIndex
        if isBegan then
            otherIndex = index + (inFront and 0 or 1)
        else
            otherIndex = index + (inFront and -1 or 0)
        end
        if otherIndex > endedIndex then
            return true, index - deletedCnt, inFront
        elseif otherIndex > beganIndex then
            if beganIndex <= totalLength or totalLength < 1 then
                return true, beganIndex, true
            else
                return true, totalLength, false
            end
        else
            return false
        end
    end

    local function updateCursorIndices(otherCursor)
        local otherBeganIndex, otherBeganInFront, otherEndedIndex, otherEndedInFront = otherCursor:getIndices()
        local otherIsSelected = otherCursor:isSelected()
        local needUpdateCursor = true
        needUpdateCursor, otherBeganIndex, otherBeganInFront = getDeletedCursorIndices(otherBeganIndex, otherBeganInFront, true)
        if not otherIsSelected then
            if needUpdateCursor then
                otherCursor:setIndices(otherBeganIndex, otherBeganInFront)
            end
        else
            if needUpdateCursor then
                otherCursor:updateBeganIndex(otherBeganIndex, otherBeganInFront)
            end
            needUpdateCursor, otherEndedIndex, otherEndedInFront = getDeletedCursorIndices(otherEndedIndex, otherEndedInFront, false)
            if needUpdateCursor then
                otherCursor:updateEndedIndex(otherEndedIndex, otherEndedInFront)
            end
        end
    end

    table.foreach(self.cursors, function(id, otherCursor)
        if id ~= uid then
            updateCursorIndices(otherCursor)
        end
    end)
end

function JQRichTextModel:updateOtherCursorIndicesByDeleteAhead(uid, oldIndex, oldInFront)
    local cursor = self:getOrCreateCursor(uid)
    local index, inFront = cursor:getEndedIndex()
    local deletedCnt = oldIndex - index
    if inFront == true and oldInFront == false then
        deletedCnt = deletedCnt + 1
    elseif inFront == false and oldInFront == true then
        deletedCnt = deletedCnt - 1
    end

    self:updateOtherCursorIndicesWithOffset(uid, oldIndex, oldInFront, -deletedCnt)
end

function JQRichTextModel:updateOtherCursorIndicesByDeleteBehind(uid, oldIndex, oldInFront)
    self:updateOtherCursorIndicesWithOffset(uid, oldIndex, oldInFront, -1)
end

function JQRichTextModel:updateOtherCursorIndicesWithOffset(uid, oldIndex, oldInFront, offset)
    oldIndex = oldIndex + (oldInFront and 0 or 1)
    table.foreach(self.cursors, function(id, otherCursor)
        if id ~= uid then
            local otherBeganIndex, otherBeganInFront, otherEndedIndex, otherEndedInFront = otherCursor:getIndices()
            local otherIsSelected = otherCursor:isSelected()
            local otherIndex = otherBeganIndex + (otherBeganInFront and 0 or 1)
            if not otherIsSelected then
                if otherIndex > oldIndex then
                    otherCursor:setIndices(otherBeganIndex + offset, otherBeganInFront)
                end
            else
                if otherIndex > oldIndex then
                    otherCursor:updateBeganIndex(otherBeganIndex + offset, otherBeganInFront)
                end
                otherIndex = otherEndedIndex + (otherEndedInFront and -1 or 0)
                if otherIndex > oldIndex then
                    otherCursor:updateEndedIndex(otherEndedIndex + offset, otherEndedInFront)
                end
            end
        end
    end)
end

function JQRichTextModel:updateCursorIndicesAndFormat(uid, beganIndex, beganInFront, endedIndex, endedInFront, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local formatIndex = self:getFormatIndicesByIndex(endedIndex, endedInFront)
    cursor:setFormat(self.formats[formatIndex])
    self:updateCursorIndices(uid, beganIndex, beganInFront, endedIndex, endedInFront, isFromReplay)
    if self.dataNotification and not isFromReplay then
        self:dispatchEvent({name = JQRichTextModel.EVENT_CURSOR_FORMAT_CHANGED, uid = uid})
    end
end

function JQRichTextModel:updateCursorIndices(uid, beganIndex, beganInFront, endedIndex, endedInFront, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    cursor:updateBeganIndex(beganIndex, beganInFront)
    cursor:updateEndedIndex(endedIndex, endedInFront)
    if self.dataNotification and not isFromReplay then
        self:dispatchEvent({name = JQRichTextModel.EVENT_CURSOR_INDICES_CHANGED, uid = uid})
    end
end

function JQRichTextModel:updateCursorGroupByFormatIndex(uid, isFromReplay)
    local cursor = self:getOrCreateCursor(uid)
    local index, inFront = cursor:getEndedIndex()
    local formatIndex = self:getFormatIndicesByIndex(index, inFront)
    local groupAlign = self.formats[formatIndex].groupAlign
    local groupIndex = self.formats[formatIndex].groupIndex
    cursor:updateFormatByName(JQRichTextConstants.HTML.FORMAT_GROUP_INDEX, groupIndex)
    cursor:updateFormatByName(JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN, groupAlign)
    if self.dataNotification and not isFromReplay then
        self:dispatchEvent({name = JQRichTextModel.EVENT_CURSOR_FORMAT_CHANGED,
                            uid = uid,
                            formatName = JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN,
                            formatValue = groupAlign,
                            groupIndex = groupIndex})
    end
end

function JQRichTextModel:updateCursorFormatByName(uid, formatName, formatValue, isFromReplay)
    if formatName == JQRichTextConstants.HTML.FORMAT_COLOR or formatName == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
        if formatValue and JQRichTextUtils:isHexColor(formatValue) then
            formatValue = JQRichTextUtils:toColor(formatValue)
        end
    end
    local cursor = self:getOrCreateCursor(uid)
    cursor:updateFormatByName(formatName, formatValue)
    if self.dataNotification and not isFromReplay then
        self:dispatchEvent({name = JQRichTextModel.EVENT_CURSOR_FORMAT_CHANGED,
                            uid = uid,
                            formatName = formatName,
                            formatValue = formatValue})
    end
end

function JQRichTextModel:updateCursorFormat(uid, format)
    local newFormat = {}
    table.walk(format, function(formatValue, formatName)
        formatValue = self:convertToColor(formatName, formatValue, newFormat)
        newFormat[formatName] = formatValue
    end)
    local cursor = self:getOrCreateCursor(uid)
    cursor:mergeFormat(newFormat)
    if self.dataNotification then
        self:dispatchEvent({name = JQRichTextModel.EVENT_CURSOR_FORMAT_CHANGED, uid = uid})
    end
end

function JQRichTextModel:convertToColor(formatName, formatValue, format)
    if formatName == JQRichTextConstants.HTML.FORMAT_COLOR or formatName == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
        if not formatValue then
            if formatName == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
                format[JQRichTextConstants.HTML.FORMAT_HAS_BG_COLOR] = false
            end
        elseif JQRichTextUtils:isHexColor(formatValue) then
            formatValue = JQRichTextUtils:toColor(formatValue)
        end
    end
    return formatValue
end

function JQRichTextModel:resetAllCursorIndices()
    table.walk(self.cursors, function(cursor)
        cursor:setIndices(-1, false)
    end)
end

function JQRichTextModel:getCursorIndices(uid)
    local cursor = self:getOrCreateCursor(uid)
    return cursor:getIndices()
end

function JQRichTextModel:getCurrentCursorIndex(uid)
    local cursor = self:getOrCreateCursor(uid)
    return cursor:getEndedIndex()
end

function JQRichTextModel:isCursorExist(uid)
    local endedIndex = self:getCurrentCursorIndex(uid)
    return endedIndex > -1
end

function JQRichTextModel:getCursors()
    return self.cursors
end

--- only for server
function JQRichTextModel:getCursorsInServer()
    local cursors = {}
    table.walk(self.cursors, function(cursor, uid)
        local indices = {cursor:getIndices()}
        local format = cursor:getFormatInServer()
        cursors[uid] = {
            indices = indices,
            format = format
        }
    end)
    return cursors
end

--- only for server
function JQRichTextModel:getDefaultFormatInServer()
    local formats = self.defaultFormat:getChangedProperties()
    return formats
end

function JQRichTextModel:modifyCursorId(oldId, newId)
    if not self.cursors[oldId] then
        return
    end

    self.cursors[newId] = self.cursors[oldId]
    self.cursors[oldId] = nil
end

function JQRichTextModel:getOrCreateCursor(uid)
    uid = uid or JQRichTextConstants.DEFAULT_ID
    if not self.cursors[uid] then
        self.cursors[uid] = JQRichTextCursorModel.new({defaultFormat = self.defaultFormat:clone()})
    end
    return self.cursors[uid]
end

function JQRichTextModel:backup()
    self.backupFormats = {}
    self.backupCursors = {}
    table.foreach(self.formats, function(_, format)
        table.insert(self.backupFormats, format:copyProperties())
    end)
    table.walk(self.cursors, function(cursor, uid)
        self.backupCursors[uid] = cursor:clone()
    end)
end

function JQRichTextModel:useBackup()
    self.formats = {}
    self.cursors = {}
    table.foreach(self.backupFormats, function(_, format)
        table.insert(self.formats, JQRichTextFormatModel.new(format))
    end)
    table.walk(self.backupCursors, function(cursor, uid)
        cursor.defaultFormat = JQRichTextFormatModel.new(cursor.formatProperties)
        self.cursors[uid] = JQRichTextCursorModel.new(cursor)
    end)
    if self.dataNotification then
        self:dispatchChangedEvent()
    end
end

function JQRichTextModel:dispatchChangedEvent(uid,formatName)
    self:dispatchEvent({name = JQRichTextModel.EVENT_TEXT_CHANGED, uid = uid,formatName = formatName})
end

return JQRichTextModel
